import React, { useState, useMemo } from "react";
import * as XLSX from "xlsx";
import {
  Box,
  Container,
  Typography,
  Paper,
  Input,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Card,
  CardContent,
  LinearProgress,
  Tooltip,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
} from "@mui/material";
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, Legend, LabelList } from "recharts";

interface Job {
  [key: string]: any;
}

interface InstallerStats {
  installer: string;
  totalJobs: number;
  problemJobs: number;
  problemJobTypeCounts: Record<string, number>;
  jobs: Job[];
}

const columns = [
  "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K"
];

// Chart color palette
const chartColors = [
  "#f87171", "#fbbf24", "#34d399", "#60a5fa", "#a78bfa", "#f472b6", "#38bdf8", "#fcd34d", "#c084fc", "#facc15"
];

// Utility: Extract problem types from column F for all jobs
const extractProblemTypes = (jobs: Job[]): string[] => {
  const types = new Set<string>();
  jobs.forEach(job => {
    const reason = typeof job["F"] === "string" ? job["F"].trim() : "";
    if (reason) {
      // If multiple reasons are comma-separated, split them (optional, comment out if not desired)
      reason.split(",").forEach(r => types.add(r.trim()));
    }
  });
  return Array.from(types).sort();
};

// Utility: Calculate installer stats for a given problem type
const getInstallersStats = (jobs: Job[], problemType: string | null): InstallerStats[] => {
  const installerMap: Record<string, InstallerStats> = {};
  jobs.forEach((job) => {
    const installer = job["C"] || "Unknown";
    const reason = typeof job["F"] === "string" ? job["F"].trim() : "";

    if (!installerMap[installer]) {
      installerMap[installer] = {
        installer,
        totalJobs: 0,
        problemJobs: 0,
        problemJobTypeCounts: {},
        jobs: [],
      };
    }
    installerMap[installer].totalJobs += 1;
    installerMap[installer].jobs.push(job);

    // Count all problem types for this installer
    if (reason) {
      if (!installerMap[installer].problemJobTypeCounts[reason]) {
        installerMap[installer].problemJobTypeCounts[reason] = 0;
      }
      installerMap[installer].problemJobTypeCounts[reason]++;
    }

    // If comparing a specific problem type, increment for that type
    if (problemType) {
      // Allow partial match for "Customer Satisfaction", "Rescheduled in Route", etc.
      if (reason.toLowerCase().includes(problemType.toLowerCase())) {
        installerMap[installer].problemJobs += 1;
      }
    } else {
      // Default: count all jobs with any issue (i.e., any reason)
      if (reason) {
        installerMap[installer].problemJobs += 1;
      }
    }
  });
  return Object.values(installerMap);
};

const getProblemChild = (stats: InstallerStats[]): InstallerStats | null => {
  if (!stats.length) return null;
  // Sort by problemJobs descending, then totalJobs descending
  return stats
    .slice()
    .sort(
      (a, b) =>
        b.problemJobs / (b.totalJobs || 1) - a.problemJobs / (a.totalJobs || 1) ||
        b.problemJobs - a.problemJobs ||
        b.totalJobs - a.totalJobs
    )[0];
};

const App: React.FC = () => {
  const [jobs, setJobs] = useState<Job[]>([]);
  const [problemTypes, setProblemTypes] = useState<string[]>([]);
  const [compareType, setCompareType] = useState<string>(""); // Empty string means "Overall %"
  const [installerStats, setInstallerStats] = useState<InstallerStats[]>([]);
  const [problemChild, setProblemChild] = useState<InstallerStats | null>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const data = evt.target?.result;
      if (typeof data !== "string" && !(data instanceof ArrayBuffer)) return;
      const workbook = XLSX.read(data, { type: "binary" });
      const firstSheetName = workbook.SheetNames[0];
      const sheet = workbook.Sheets[firstSheetName];
      const parsedJobs = parseJobs(sheet);
      setJobs(parsedJobs);
      const types = extractProblemTypes(parsedJobs);
      setProblemTypes(types);

      // Default: compare by overall %
      const stats = getInstallersStats(parsedJobs, null);
      setInstallerStats(stats);
      setProblemChild(getProblemChild(stats));
      setCompareType(""); // default to "overall"
    };
    reader.readAsBinaryString(file);
  };

  // When compareType changes, update installerStats and problemChild accordingly
  React.useEffect(() => {
    if (!jobs.length) {
      setInstallerStats([]);
      setProblemChild(null);
      return;
    }
    const stats = getInstallersStats(jobs, compareType || null);
    setInstallerStats(stats);
    setProblemChild(getProblemChild(stats));
  }, [jobs, compareType]);

  // Chart data
  const chartData = useMemo(() => {
    return installerStats.map((stat, idx) => {
      const percent = stat.totalJobs ? (stat.problemJobs / stat.totalJobs) * 100 : 0;
      return {
        name: stat.installer,
        "Problem %": Number(percent.toFixed(1)),
        "Problem Jobs": stat.problemJobs,
        "Total Jobs": stat.totalJobs,
        color: chartColors[idx % chartColors.length]
      };
    });
  }, [installerStats]);

  // Helper to get human-readable label for current compareType
  const getCompareTypeLabel = () => {
    if (!compareType) return "Overall % of Problem Jobs";
    return `% of "${compareType}" Jobs`;
  };

  // Table of problem jobs for the current problem child and reason
  const problemJobsForProblemChild = useMemo(() => {
    if (!problemChild) return [];
    if (!compareType) {
      // All problem jobs
      return problemChild.jobs.filter(
        (j) => typeof j["F"] === "string" && j["F"].trim()
      );
    } else {
      // Only jobs that match the selected reason
      return problemChild.jobs.filter(
        (j) =>
          typeof j["F"] === "string" &&
          j["F"].toLowerCase().includes(compareType.toLowerCase())
      );
    }
  }, [problemChild, compareType]);

  return (
    <Box sx={{ bgcolor: "#f8fafc", minHeight: "100vh", py: 6 }}>
      <Container maxWidth="lg">
        <Paper elevation={4} sx={{ p: 4, borderRadius: 3, mb: 5 }}>
          <Typography variant="h3" fontWeight={700} gutterBottom color="primary">
            Problem Child Installer Analyzer
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
            Upload your <b>.xlsx</b> file to analyze which installer is having the most issues. Instantly compare all installers by any reason found in your data!
          </Typography>
          <Input
            type="file"
            inputProps={{ accept: ".xlsx, .xls" }}
            onChange={handleFile}
            sx={{ my: 2 }}
          />
        </Paper>

        {installerStats.length > 0 && (
          <>
            <Box sx={{ display: "flex", gap: 3, flexWrap: "wrap", mb: 5 }}>
              <Card sx={{ minWidth: 320, bgcolor: "#f5f5f5" }}>
                <CardContent>
                  <Typography variant="h5" gutterBottom color="error" fontWeight={700}>
                    Problem Child
                  </Typography>
                  {problemChild ? (
                    <>
                      <Typography variant="h6" sx={{ fontWeight: 600 }}>
                        {problemChild.installer}
                      </Typography>
                      <Typography sx={{ mt: 1 }}>
                        Total Jobs: <b>{problemChild.totalJobs}</b>
                      </Typography>
                      <Typography>
                        Problem Jobs: <b style={{ color: "#d32f2f" }}>{problemChild.problemJobs}</b>
                        &nbsp;|&nbsp;
                        <span style={{
                          background: "#ffeaea",
                          borderRadius: 8,
                          padding: "2px 10px",
                          marginLeft: 6,
                          fontWeight: 600,
                          color: "#d32f2f"
                        }}>
                          {problemChild.totalJobs
                            ? `${((problemChild.problemJobs / problemChild.totalJobs) * 100).toFixed(1)}%`
                            : "0%"}
                        </span>
                      </Typography>
                      <Box sx={{ mt: 3 }}>
                        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                          Percentage of Problem Jobs
                        </Typography>
                        <LinearProgress
                          variant="determinate"
                          value={problemChild.totalJobs ? (problemChild.problemJobs / problemChild.totalJobs) * 100 : 0}
                          sx={{
                            height: 12,
                            borderRadius: 6,
                            backgroundColor: "#e0e0e0",
                            "& .MuiLinearProgress-bar": {
                              backgroundColor: "#d32f2f",
                            },
                          }}
                        />
                      </Box>
                    </>
                  ) : (
                    <Typography>No data found.</Typography>
                  )}
                </CardContent>
              </Card>

              <Card sx={{ flex: 1, minWidth: 420, bgcolor: "#f5f5f5" }}>
                <CardContent>
                  <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                    <Typography variant="h6" sx={{ flex: 1 }}>
                      Installer Comparison
                    </Typography>
                    <FormControl size="small" sx={{ minWidth: 240 }}>
                      <InputLabel id="compare-type-label">Compare by</InputLabel>
                      <Select
                        labelId="compare-type-label"
                        value={compareType}
                        label="Compare by"
                        onChange={e => setCompareType(e.target.value)}
                      >
                        <MenuItem value="">
                          Overall % of Problem Jobs
                        </MenuItem>
                        {problemTypes.map((type) => (
                          <MenuItem value={type} key={type}>
                            % of "{type}" Jobs
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Box>
                  <Typography variant="body2" sx={{ mb: 1, color: "#555" }}>
                    {getCompareTypeLabel()}
                  </Typography>
                  <Box sx={{ height: 290 }}>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData} margin={{ top: 20, right: 20, left: 0, bottom: 30 }}>
                        <XAxis dataKey="name" angle={-20} textAnchor="end" height={60} interval={0} />
                        <YAxis allowDecimals={false} domain={[0, 100]} tickFormatter={v => v + "%"} />
                        <RechartsTooltip formatter={(value: any, name: string) =>
                          name === "Problem %" ? `${value}%` : value} />
                        <Legend verticalAlign="top" />
                        <Bar dataKey="Problem %" fill="#d32f2f" radius={[8, 8, 0, 0]}>
                          <LabelList dataKey="Problem %" position="top" formatter={(v: number) => `${v}%`} />
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </Box>
                  <Typography variant="caption" color="text.secondary">
                    <span style={{ color: "#d32f2f", fontWeight: 700 }}>Red</span> = Percentage of Problem Jobs for Each Installer
                  </Typography>
                </CardContent>
              </Card>
            </Box>

            {problemChild && (
              <Paper elevation={3} sx={{ mb: 5, p: 3, borderRadius: 2 }}>
                <Typography variant="h6" color="error" fontWeight={600} sx={{ mb: 2 }}>
                  Problem Jobs for {problemChild.installer}
                  {compareType ? <> ({compareType})</> : null}
                </Typography>
                {problemJobsForProblemChild.length > 0 ? (
                  <TableContainer sx={{ borderRadius: 2 }}>
                    <Table size="small">
                      <TableHead sx={{ bgcolor: "#f7eaea" }}>
                        <TableRow>
                          {columns.map((col) => (
                            <TableCell key={col}><b>{col}</b></TableCell>
                          ))}
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {problemJobsForProblemChild.map((job, idx) => (
                          <TableRow key={idx}>
                            {columns.map((col) => (
                              <TableCell key={col}>{job[col]}</TableCell>
                            ))}
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                ) : (
                  <Typography color="text.secondary">None found for this installer.</Typography>
                )}
              </Paper>
            )}

            <Paper elevation={1} sx={{ p: 3, borderRadius: 2 }}>
              <Typography variant="h6" fontWeight={600} sx={{ mb: 2 }}>
                All Jobs List
              </Typography>
              <TableContainer sx={{ borderRadius: 2 }}>
                <Table size="small">
                  <TableHead sx={{ bgcolor: "#e3e3e3" }}>
                    <TableRow>
                      {columns.map((col) => (
                        <TableCell key={col}><b>{col}</b></TableCell>
                      ))}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {jobs.map((job, idx) => (
                      <TableRow key={idx}>
                        {columns.map((col) => (
                          <TableCell key={col}>{job[col]}</TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </>
        )}

        {!installerStats.length && (
          <Paper sx={{ mt: 6, p: 4, color: "#888", textAlign: "center" }}>
            <Typography variant="h6" color="text.secondary">
              Please upload an .xlsx file to get started.
            </Typography>
          </Paper>
        )}

        <Box sx={{ mt: 8, mb: 2, textAlign: "center", color: "#bbb" }}>
          <Typography variant="caption">
            &copy; {new Date().getFullYear()} Problem Child Analyzer for Installers
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

// Parse jobs from worksheet
function parseJobs(sheet: XLSX.WorkSheet): Job[] {
  const rows: any[][] = XLSX.utils.sheet_to_json(sheet, { header: 1 });
  if (rows.length < 2) return [];
  const jobs: Job[] = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const job: Job = {};
    // Store columns from A to K (0-10)
    for (let col = 0; col <= 10; col++) {
      job[String.fromCharCode("A".charCodeAt(0) + col)] = row[col] ?? "";
    }
    jobs.push(job);
  }
  return jobs;
}

export default App;